from __future__ import annotations

from dataclasses import dataclass


def _non_empty(field_name: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class PromptRevision:
    prompt_id: str
    revision_id: str
    model_id: str
    prompt_hash: str
    author: str

    def __post_init__(self) -> None:
        _non_empty("prompt_id", self.prompt_id)
        _non_empty("revision_id", self.revision_id)
        _non_empty("model_id", self.model_id)
        _non_empty("prompt_hash", self.prompt_hash)
        _non_empty("author", self.author)

    def asset_anchor(self) -> tuple[str, str, str]:
        return (self.prompt_id, self.revision_id, self.model_id)


@dataclass(frozen=True)
class EvaluationResult:
    prompt_id: str
    revision_id: str
    model_id: str
    dataset_version: str
    risk_score: int
    passed: bool

    def __post_init__(self) -> None:
        _non_empty("prompt_id", self.prompt_id)
        _non_empty("revision_id", self.revision_id)
        _non_empty("model_id", self.model_id)
        _non_empty("dataset_version", self.dataset_version)
        if not 0 <= self.risk_score <= 100:
            raise ValueError("risk_score must be between 0 and 100")

    def evidence_anchor(self) -> tuple[str, str, str]:
        return (self.prompt_id, self.revision_id, self.model_id)


@dataclass(frozen=True)
class ApprovalEvent:
    prompt_id: str
    revision_id: str
    approver: str
    ticket_id: str

    def __post_init__(self) -> None:
        _non_empty("prompt_id", self.prompt_id)
        _non_empty("revision_id", self.revision_id)
        _non_empty("approver", self.approver)
        _non_empty("ticket_id", self.ticket_id)

    def covers_revision(self, prompt_id: str, revision_id: str) -> bool:
        return self.prompt_id == prompt_id and self.revision_id == revision_id


def risk_band(score: int) -> str:
    if score < 30:
        return "low"
    if score < 70:
        return "medium"
    return "high"


def anchors_equal(left: tuple[str, str, str], right: tuple[str, str, str]) -> bool:
    return left == right


def describe_asset_tuple(anchor: tuple[str, str, str]) -> str:
    prompt_id, revision_id, model_id = anchor
    return f"{prompt_id}#{revision_id}@{model_id}"


def is_high_risk_score(score: int, threshold: int = 70) -> bool:
    if threshold < 0 or threshold > 100:
        raise ValueError("threshold must be between 0 and 100")
    return score >= threshold

