from __future__ import annotations

"""Lineage predicates for watsonx.governance factsheets (starter uses model-only evaluation matching)."""

from governance_models import ApprovalEvent, EvaluationResult, PromptRevision


def evaluation_matches_model_only(evaluation: EvaluationResult, prompt: PromptRevision) -> bool:
    """BUGGY compatibility shim: trusts any evaluation row sharing the same `model_id`."""
    return evaluation.model_id == prompt.model_id


def evaluation_matches_full_tuple(evaluation: EvaluationResult, prompt: PromptRevision) -> bool:
    """Strict lineage: prompt id, revision id, and model id must align."""
    return (
        evaluation.prompt_id == prompt.prompt_id
        and evaluation.revision_id == prompt.revision_id
        and evaluation.model_id == prompt.model_id
    )


def approval_matches_revision(approval: ApprovalEvent, prompt: PromptRevision) -> bool:
    return approval.prompt_id == prompt.prompt_id and approval.revision_id == prompt.revision_id


def revision_anchor_id(prompt: PromptRevision) -> str:
    return f"{prompt.prompt_id}:{prompt.revision_id}"


def evaluation_anchor_id(evaluation: EvaluationResult) -> str:
    return f"{evaluation.prompt_id}:{evaluation.revision_id}:{evaluation.model_id}"


def first_matching_evaluation(
    prompt: PromptRevision,
    evaluations: list[EvaluationResult],
    predicate,
) -> EvaluationResult | None:
    for row in evaluations:
        if predicate(row, prompt):
            return row
    return None


def first_matching_approval(prompt: PromptRevision, approvals: list[ApprovalEvent]) -> ApprovalEvent | None:
    for row in approvals:
        if approval_matches_revision(row, prompt):
            return row
    return None


def collect_warnings(evaluation: EvaluationResult | None, approval: ApprovalEvent | None) -> list[str]:
    warnings: list[str] = []
    if evaluation is None:
        warnings.append("missing_evaluation")
    if approval is None:
        warnings.append("missing_approval")
    return warnings


def dataset_fingerprint(evaluation: EvaluationResult | None) -> str | None:
    if evaluation is None:
        return None
    return f"{evaluation.dataset_version}@{evaluation.risk_score}"


def sort_evaluations_by_risk(evaluations: list[EvaluationResult]) -> list[EvaluationResult]:
    return sorted(evaluations, key=lambda row: row.risk_score)


def approvals_for_prompt_id(approvals: list[ApprovalEvent], prompt_id: str) -> list[ApprovalEvent]:
    return [row for row in approvals if row.prompt_id == prompt_id]


def evaluations_for_model_id(evaluations: list[EvaluationResult], model_id: str) -> list[EvaluationResult]:
    return [row for row in evaluations if row.model_id == model_id]


def partition_audit_ready(
    factsheets: list[dict[str, object]],
) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
    ready: list[dict[str, object]] = []
    not_ready: list[dict[str, object]] = []
    for sheet in factsheets:
        warnings = sheet.get("warnings", [])
        if sheet.get("evaluation_passed") is True and sheet.get("approval_status") == "approved" and not warnings:
            ready.append(sheet)
        else:
            not_ready.append(sheet)
    return ready, not_ready


def describe_lineage_gap(prompt: PromptRevision, evaluation: EvaluationResult | None) -> str:
    if evaluation is None:
        return f"no_evaluation_row_for::{revision_anchor_id(prompt)}"
    if not evaluation_matches_full_tuple(evaluation, prompt):
        return (
            f"evaluation_prompt_revision_mismatch expected={revision_anchor_id(prompt)} "
            f"found={evaluation.prompt_id}:{evaluation.revision_id}"
        )
    return "lineage_ok"

